import requests

MAPA_ERROS = {401: "acesso negado", 404: "recurso ausente", 500: "erro do servidor"}

def chamar_api(caminho, headers=None):
    resp = requests.get("https://api.dojo.dev" + caminho, headers=headers)
    if resp.status_code == 200:
        return {"ok": True, "dados": resp.json()}
    rotulo = MAPA_ERROS.get(resp.status_code, f"erro {resp.status_code}")
    try:
        detalhe = resp.json().get("erro", resp.text)
    except requests.exceptions.JSONDecodeError:
        detalhe = resp.text
    return {"ok": False, "mensagem": f"{rotulo}: {detalhe}"}

import requests

def coletar_usuarios():
    usuarios = {}
    pagina = 1
    while True:
        resp = requests.get("https://api.dojo.dev/usuarios", params={"pagina": pagina})
        if resp.status_code != 200:
            raise RuntimeError(f"falha na página {pagina}: status {resp.status_code}")
        dados = resp.json()["dados"]
        if not dados:
            return usuarios
        for u in dados:
            usuarios[u["nome"]] = u["time"]
        pagina += 1

