import requests

def listar_modelos(limite_paginas=10):
    nomes = []
    cursor = None
    for _ in range(limite_paginas):
        params = {} if cursor is None else {"cursor": cursor}
        resp = requests.get("https://api.dojo.dev/modelos", params=params)
        corpo = resp.json()
        for m in corpo["modelos"]:
            nomes.append(m["nome"])
        proximo = corpo["proximo_cursor"]
        if proximo is None:
            return nomes
        if proximo == cursor:
            raise RuntimeError("paginação presa em loop: cursor repetido")
        cursor = proximo
    raise RuntimeError(f"limite de {limite_paginas} páginas atingido sem terminar")

