class ErroPermanente(Exception):
    def __init__(self, status):
        super().__init__(f"erro permanente: status {status}")
        self.status = status

def buscar_resiliente(caminho, max_tentativas):
    for _ in range(max_tentativas):
        resp = requests.get("https://api.dojo.dev" + caminho)
        if resp.status_code == 200:
            return resp.json()
        if resp.status_code not in (429, 500):
            raise ErroPermanente(resp.status_code)
    return None

