import requests
import time

def retry_com_orcamento(caminho, orcamento_s, base):
    inicio = time.monotonic()
    tentativa = 0
    while True:
        resp = requests.get("https://api.dojo.dev" + caminho)
        if resp.status_code == 200:
            return resp.json()
        if resp.status_code not in (429, 500):
            return None
        espera = base * (2 ** tentativa) + 0.1 * tentativa
        if (time.monotonic() - inicio) + espera > orcamento_s:
            return None
        time.sleep(espera)
        tentativa += 1

import asyncio
import requests

async def sondar_rotas(caminhos):
    async def uma(caminho):
        resp = await requests.aget("https://api.dojo.dev" + caminho)
        return resp.json()

    resultados = await asyncio.gather(
        *[uma(c) for c in caminhos], return_exceptions=True
    )
    corpos = []
    falhas = 0
    for r in resultados:
        if isinstance(r, Exception):
            falhas += 1
        else:
            corpos.append(r)
    return {"corpos": corpos, "falhas": falhas}

