import numpy as np

def indice_mais_parecido(matriz, consulta):
    consulta = np.array(consulta, dtype=float)
    norma_consulta = np.linalg.norm(consulta)
    scores = []
    for linha in matriz:
        v = np.array(linha, dtype=float)
        scores.append(float(np.dot(v, consulta) / (np.linalg.norm(v) * norma_consulta)))
    return int(np.argmax(scores))

