import numpy as np

def cosseno_seguro(a, b):
    a = np.array(a, dtype=float)
    b = np.array(b, dtype=float)
    norma_a = float(np.linalg.norm(a))
    norma_b = float(np.linalg.norm(b))
    if norma_a == 0.0 or norma_b == 0.0:
        return 0.0
    return float(np.dot(a, b) / (norma_a * norma_b))

